const fs = require('fs-extra');
const path = require('path');
const os = require('os');

const ClaudeIntegration = require('../../lib/integrations/claude-integration');
const { SKILLS } = require('../../lib/skills/registry');

const MARKER =
  '<!-- Generated by ContextKit (@nolrm/contextkit) https://www.npmjs.com/package/@nolrm/contextkit -->';

describe('ClaudeIntegration', () => {
  let tempDir;
  let originalCwd;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'contextkit-claude-'));
    originalCwd = process.cwd();
    process.chdir(tempDir);
  });

  afterEach(async () => {
    process.chdir(originalCwd);
    await fs.remove(tempDir);
  });

  test('1. CLAUDE.md imports AGENTS.md and the project index', async () => {
    await new ClaudeIntegration().install();

    const content = await fs.readFile('CLAUDE.md', 'utf-8');
    expect(content).toContain(MARKER);
    expect(content).toMatch(/^@AGENTS\.md$/m);
    expect(content).toMatch(/^@\.contextkit\/standards\/index\.md$/m);
    expect(content).toContain('AskUserQuestion');
    expect(content).not.toContain('squad');
    expect(content).not.toContain('response_style');
  });

  test('2. writes the canonical AGENTS.md alongside CLAUDE.md', async () => {
    await new ClaudeIntegration().install();

    const content = await fs.readFile('AGENTS.md', 'utf-8');
    expect(content).toContain('Read `.contextkit/standards/index.md` first');
    expect(content).toContain('status: active');
  });

  test('3. renders path-scoped rules with paths: (not globs:) from the default context rules', async () => {
    await new ClaudeIntegration().install();

    const testing = await fs.readFile('.claude/rules/contextkit-testing.md', 'utf-8');
    expect(testing).toMatch(/^paths:\n {2}- "\*\*\/\*\.test\.\*"/m);
    expect(testing).not.toContain('globs:');
    expect(testing).toContain('@.contextkit/standards/testing.md');

    const codeStyle = await fs.readFile('.claude/rules/contextkit-code-style.md', 'utf-8');
    expect(codeStyle).toContain('  - "src/**"');
  });

  test('4. renders rules from config.yml context_rules and drops stale contextkit-* rules', async () => {
    await fs.ensureDir('.contextkit');
    await fs.writeFile(
      '.contextkit/config.yml',
      'context_rules:\n  - file: standards/state-guide.md\n    paths: ["src/store/**"]\n'
    );
    await fs.ensureDir('.claude/rules');
    await fs.writeFile('.claude/rules/contextkit-testing.md', 'old');
    await fs.writeFile('.claude/rules/my-own-rule.md', 'mine');

    await new ClaudeIntegration().install();

    const rule = await fs.readFile('.claude/rules/contextkit-state-guide.md', 'utf-8');
    expect(rule).toContain('  - "src/store/**"');
    expect(await fs.pathExists('.claude/rules/contextkit-testing.md')).toBe(false);
    expect(await fs.pathExists('.claude/rules/my-own-rule.md')).toBe(true);
  });

  test('5. creates all registry skills as .claude/skills/<name>/SKILL.md with frontmatter', async () => {
    await new ClaudeIntegration().install();

    for (const skill of SKILLS) {
      const content = await fs.readFile(`.claude/skills/${skill.name}/SKILL.md`, 'utf-8');
      expect(content.startsWith('---\n')).toBe(true);
      expect(content).toContain(`description: ${skill.description}`);
      expect(content).toContain(`.contextkit/${skill.source}`);
    }
  });

  test('6. keeps custom CLAUDE.md content outside the ContextKit block', async () => {
    await fs.writeFile('CLAUDE.md', '# My Custom Claude Config\n\nCustom rules here.\n');

    await new ClaudeIntegration().install();

    const content = await fs.readFile('CLAUDE.md', 'utf-8');
    expect(content).toContain('# My Custom Claude Config');
    expect(content).toContain('Custom rules here.');
    expect(content).toContain(MARKER);
  });

  test('7. validate returns valid after install', async () => {
    const integration = new ClaudeIntegration();
    await integration.install();
    expect((await integration.validate()).valid).toBe(true);
  });

  test('8. validate returns invalid before install', async () => {
    expect((await new ClaudeIntegration().validate()).valid).toBe(false);
  });

  test('9. CLAUDE.md includes ContextKit version stamp matching package.json', async () => {
    await new ClaudeIntegration().install();
    const { version } = require('../../package.json');
    expect(await fs.readFile('CLAUDE.md', 'utf-8')).toContain(`Version: ${version}`);
  });

  test('10. removes retired skills, legacy commands, and the old always-on standards rule', async () => {
    await fs.ensureDir('.claude/skills/squad-auto');
    await fs.writeFile('.claude/skills/squad-auto/SKILL.md', 'old');
    await fs.ensureDir('.claude/commands');
    await fs.writeFile('.claude/commands/analyze.md', 'legacy');
    await fs.ensureDir('.claude/rules');
    await fs.writeFile('.claude/rules/contextkit-standards.md', 'old');

    await new ClaudeIntegration().install();

    expect(await fs.pathExists('.claude/skills/squad-auto')).toBe(false);
    expect(await fs.pathExists('.claude/commands/analyze.md')).toBe(false);
    expect(await fs.pathExists('.claude/rules/contextkit-standards.md')).toBe(false);
  });

  test('11. does not write .claude/settings.json even when Node.js format/lint tooling is present', async () => {
    await fs.writeJson('package.json', {
      scripts: { format: 'prettier --write .', lint: 'eslint .' },
    });
    await new ClaudeIntegration().install();
    expect(await fs.pathExists('.claude/settings.json')).toBe(false);
  });

  test('12. goal skill can dispatch a reviewer (Task in allowed-tools)', async () => {
    await new ClaudeIntegration().install();
    const content = await fs.readFile('.claude/skills/goal/SKILL.md', 'utf-8');
    expect(content).toMatch(/^allowed-tools: .*Task/m);
  });
});
